L113: "output": "import type { MarketTick } from \"../types\";\nimport type MarketDataService from \"./MarketDataService\";\nimport type TradingEngine from \"./TradingEngine\";\nimport logger from \"../utils/logger\";\n\nexport type EvaluationMode = \"parallel\" | \"sequential\";\n\nexport interface TradingLoopOptions {\n    /**\n     * How to evaluate strategies on each tick.\n     * - parallel: All strategies evaluate concurrently (default, faster)\n     * - sequential: Strategies evaluate one by one (for order-dependent strategies)\n     */\n    evaluationMode?: EvaluationMode;\n\n    /**\n     * Filter strategies to specific symbols (optional optimization).\n     * If set, only strategies that care about the incoming tick symbol will evaluate.\n     */\n    filterBySymbol?: boolean;\n}\n\nexport class TradingLoopService {\n    private isRunning = false;\n    private static instance: TradingLoopService;\n    private evaluationMode: EvaluationMode = \"parallel\";\n    private filterBySymbol = false;\n    private evaluationInProgress = false;\n\n    constructor(\n        private readonly marketDataService: MarketDataService,\n        private readonly tradingEngine: TradingEngine,\n        options?: TradingLoopOptions\n    ) {\n        if (options?.evaluationMode) {\n            this.evaluationMode = options.evaluationMode;\n        }\n        if (options?.filterBySymbol !== undefined) {\n            this.filterBySymbol = options.filterBySymbol;\n        }\n    }\n\n    static getInstance(\n        marketDataService?: MarketDataService,\n        tradingEngine?: TradingEngine,\n        options?: TradingLoopOptions\n    ): TradingLoopService {\n        if (!TradingLoopService.instance) {\n            if (!marketDataService || !tradingEngine) {\n                throw new Error(\"TradingLoopService not initialized\");\n            }\n            TradingLoopService.instance = new TradingLoopService(\n                marketDataService,\n                tradingEngine,\n                options\n            );\n        }\n        return TradingLoopService.instance;\n    }\n\n    start(): void {\n        if (this.isRunning) {\n            logger.info(\"Trading loop already running\");\n            return;\n        }\n\n        this.isRunning = true;\n        this.marketDataService.on(\"tick\", this.handleTick);\n        logger.info({ evaluationMode: this.evaluationMode }, \"Trading loop started\");\n    }\n\n    stop(): void {\n        if (!this.isRunning) {\n            return;\n        }\n\n        this.isRunning = false;\n        this.marketDataService.off(\"tick\", this.handleTick);\n        logger.info(\"Trading loop stopped\");\n    }\n\n    getStatus(): { running: boolean; mode: EvaluationMode; evaluating: boolean } {\n        return {\n            running: this.isRunning,\n            mode: this.evaluationMode,\n            evaluating: this.evaluationInProgress,\n        };\n    }\n\n    setEvaluationMode(mode: EvaluationMode): void {\n        this.evaluationMode = mode;\n        logger.info({ evaluationMode: mode }, \"Evaluation mode changed\");\n    }\n\n    private handleTick = async (tick: MarketTick) => {\n        if (!this.isRunning) return;\n\n        // Skip if previous evaluation still in progress (prevent queue buildup)\n        if (this.evaluationInProgress) {\n            logger.debug({ symbol: tick.symbol }, \"Skipping tick - evaluation in progress\");\n            return;\n        }\n\n        this.evaluationInProgress = true;\n        const startTime = performance.now();\n\n        try {\n            const strategies = this.tradingEngine.getStrategies();\n\n            if (this.evaluationMode === \"parallel\") {\n                // Parallel evaluation - evaluate all strategies concurrently\n                await Promise.all(\n                    strategies.map(strategy => this.tradingEngine.evaluate(strategy.id))\n                );\n            } else {\n                // Sequential evaluation - maintain order dependency\n                for (const strategy of strategies) {\n                    await this.tradingEngine.evaluate(strategy.id);\n                }\n            }\n\n            const elapsed = performance.now() - startTime;\n            if (elapsed > 50) {\n                // Log slow evaluations (> 50ms)\n                logger.warn(\n                    { symbol: tick.symbol, elapsedMs: elapsed.toFixed(2), strategyCount: strategies.length },\n                    \"Slow strategy evaluation\"\n                );\n            }\n        } catch (error) {\n            logger.error({ err: error, symbol: tick.symbol }, \"Error in trading loop\");\n        } finally {\n            this.evaluationInProgress = false;\n        }\n    };\n}\n\nexport default TradingLoopService;\n"
L123: "text": "This is a comprehensive architectural plan to transition the current single-tenant algorithmic trading backend into a multi-tenant SaaS-style platform.\n\n### **Executive Summary**\nThe goal is to move from a single global instance (defined by `.env`) to a system where multiple users can register, configure their own broker credentials, and run independent trading strategies simultaneously.\n\n**Key Design Decisions:**\n*   **Data Isolation:** Physical separation of data using user-specific directories (LMDB) and logical separation for shared resources.\n*   **Context Scoping:** Shift from a Global Singleton Container to per-user **Service Containers**.\n*   **Event Multiplexing:** A central \"Market Data Highway\" that broadcasts ticks to all active user trading loops.\n\n---\n\n### **1. Core Architecture Changes**\n\n#### **A. User & Authentication Layer**\n*   **Current:** Single Admin API Key in `.env`.\n*   **Target:** Full User Management System.\n    *   **New Entity:** `User` (id, email, password_hash, status).\n    *   **New Service:** `AuthService` (JWT-based authentication).\n    *   **New Repository:** `UserRepository` (stores users and encrypted broker credentials).\n    *   **Middleware:** Replace `adminAuth` with `jwtAuth` which attaches `req.user` and `req.scope` (the user's DI container) to the request.\n\n#### **B. Configuration Migration (Env -> DB)**\n*   **Current:** `BROKER_API_KEY`, `ZERODHA_USER_ID`, etc., are static environment variables.\n*   **Target:** User-specific configuration stored in the database.\n    *   Users will submit their API keys via the dashboard.\n    *   These keys must be stored **encrypted at rest** (using AES-256).\n    *   The `BrokerClient` will no longer be initialized from `env` but from the user's decrypted configuration.\n\n#### **C. Dependency Injection Strategy (The \"Scope\" Pattern)**\n*   **Current:** `AppContainer` is a global singleton.\n*   **Target:** Two-tier Container System.\n    1.  **GlobalContainer:** Shared resources.\n        *   *HttpServer*, *MarketDataService* (Feed), *HistoricalDataService* (Cache), *AuthService*.\n    2.  **UserContainer (Scope):** Resources unique to a user session.\n        *   *PortfolioService* (User's DB), *TradingEngine* (User's Strategies), *BrokerClient* (User's Keys), *RiskManager* (User's Settings).\n\n---\n\n### **2. Data Layer Strategy**\n\nWe will maintain the high-performance LMDB file-based approach but partition it by user.\n\n*   **Directory Structure:**\n    ```text\n    data/\n    ├── global/             # Shared data (if any)\n    ├── users/\n    │   ├── <user-uuid-1>/\n    │   │   ├── portfolio/  # LmdbPortfolioRepository\n    │   │   ├── settings/   # LmdbSettingsRepository\n    │   │   └── audit/      # LmdbAuditLogRepository\n    │   └── <user-uuid-2>/\n    ```\n*   **Repository Factories:** Update `getPortfolioRepository()` to `getPortfolioRepository(userId)`, which dynamically resolves the path: `path.join(DATA_DIR, 'users', userId, 'portfolio')`.\n\n---\n\n### **3. Execution Engine Redesign**\n\nThe `TradingLoopService` needs a major refactor to handle multiple \"Trading Engines\".\n\n*   **Current:** One loop listens to `MarketDataService` and triggers the single `TradingEngine`.\n*   **Target:** **TradingOrchestrator** Pattern.\n    *   **MarketDataService** remains global (Single connection to AngelOne/Data Vendor).\n    *   **TradingOrchestrator** subscribes to Market Data.\n    *   On `tick(symbol)`:\n        1.  Orchestrator identifies which active Users are trading `symbol`.\n        2.  It dispatches the tick to those specific `UserTradingEngine` instances.\n        3.  Calculations run in parallel (or efficiently batched) for each user.\n\n---\n\n### **4. Migration Roadmap**\n\n#### **Phase 1: Foundation (User Identity)**\n1.  Create `User` model and `UserRepository` (using LMDB).\n2.  Implement `AuthService` (Login/Register/Encryption).\n3.  Create `UserConfig` model to store broker credentials (replacing `.env` reliance).\n\n#### **Phase 2: Data Partitioning**\n1.  Refactor `LmdbPortfolioRepository` and others to accept a `basePath` in their constructor.\n2.  Create a `RepositoryFactory` that generates these instances based on a `userId`.\n\n#### **Phase 3: Service Scoping**\n1.  Refactor `container.ts`. Remove global exports like `resolvePortfolioService`.\n2.  Create `ContainerFactory.createForUser(user: User)`.\n3.  Update API routes to use `req.scope.portfolioService` instead of global imports.\n\n#### **Phase 4: The Orchestrator**\n1.  Build `TenantManager`: Keeps track of \"Active Users\" (users with running strategies).\n2.  Refactor `TradingLoopService` to iterate over active user containers.\n\n### **Sample Code: The New Request Context**\n\n```typescript\n// middleware/context.ts\nexport const attachUserScope = async (req, res, next) => {\n  const userId = req.user.id;\n  \n  // Get or Create the DI container for this user\n  const userContainer = await ContainerManager.getForUser(userId);\n  \n  // Attach to request for use in controllers\n  req.scope = userContainer; \n  next();\n};\n\n// routes/trade.ts\nrouter.post('/order', attachUserScope, async (req, res) => {\n  // Uses the specific user's portfolio and broker connection\n  await req.scope.tradingEngine.placeOrder(req.body);\n  res.json({ success: true });\n});\n```\n\nThis plan allows the system to scale to multiple users while keeping the core algorithmic logic intact and secure."
