L165: "output": "import { promises as fs } from \"node:fs\";\nimport path from \"node:path\";\nimport logger from \"../utils/logger\";\n\nexport interface Instrument {\n  token: string;\n  symbol: string;\n  name: string;\n  expiry: string;\n  strike: string;\n  lotsize: string;\n  instrumenttype: string;\n  exch_seg: string;\n  tick_size: string;\n}\n\n/**\n * Service for managing Angel One instrument master data\n * Provides symbol-to-token mapping for API calls\n */\nexport class InstrumentMasterService {\n  private instruments: Map<string, Instrument> = new Map();\n  private symbolToTokenMap: Map<string, string> = new Map();\n  private isLoaded = false;\n  private loadingPromise: Promise<void> | null = null;\n\n  private readonly INSTRUMENT_FILE = path.join(\n    process.cwd(),\n    \"data\",\n    \"angelone-instruments.json\"\n  );\n\n  private readonly INSTRUMENT_URL =\n    \"https://margincalculator.angelbroking.com/OpenAPI_File/files/OpenAPIScripMaster.json\";\n\n  /**\n   * Download instrument master file from Angel One\n   */\n  async downloadInstrumentMaster(): Promise<void> {\n    try {\n      logger.info(\"Downloading Angel One instrument master...\");\n\n      // Ensure data directory exists\n      await fs.mkdir(path.dirname(this.INSTRUMENT_FILE), { recursive: true });\n\n      // Download file using fetch (Node 18+)\n      const response = await fetch(this.INSTRUMENT_URL);\n\n      if (!response.ok) {\n        throw new Error(`HTTP ${response.status}: ${response.statusText}`);\n      }\n\n      const data = await response.text();\n\n      // Save to file\n      await fs.writeFile(this.INSTRUMENT_FILE, data, \"utf-8\");\n\n      logger.info(\n        { path: this.INSTRUMENT_FILE },\n        \"Instrument master downloaded successfully\"\n      );\n    } catch (error) {\n      logger.error({ err: error }, \"Failed to download instrument master\");\n      throw error;\n    }\n  }\n\n  /**\n   * Load instrument master from file\n   */\n  async loadInstrumentMaster(): Promise<void> {\n    if (this.isLoaded) {\n      return;\n    }\n\n    // If loading is in progress, wait for it to complete (prevents race condition)\n    if (this.loadingPromise) {\n      await this.loadingPromise;\n      return;\n    }\n\n    this.loadingPromise = this.doLoad();\n    try {\n      await this.loadingPromise;\n    } finally {\n      this.loadingPromise = null;\n    }\n  }\n\n  /**\n   * Internal method that performs the actual loading\n   */\n  private async doLoad(): Promise<void> {\n    try {\n      try {\n        await fs.access(this.INSTRUMENT_FILE);\n      } catch {\n        // File doesn't exist, download it\n        await this.downloadInstrumentMaster();\n      }\n\n      logger.info(\"Loading Angel One instrument master...\");\n\n      const data = await fs.readFile(this.INSTRUMENT_FILE, \"utf-8\");\n      const instruments = JSON.parse(data) as Instrument[];\n\n      for (const instrument of instruments) {\n        const key = `${instrument.exch_seg}:${instrument.symbol}`;\n        this.instruments.set(key, instrument);\n        this.symbolToTokenMap.set(key, instrument.token);\n\n        // Also add without exchange prefix for convenience\n        if (!this.symbolToTokenMap.has(instrument.symbol)) {\n          this.symbolToTokenMap.set(instrument.symbol, instrument.token);\n        }\n      }\n\n      this.isLoaded = true;\n\n      logger.info(\n        { count: instruments.length },\n        \"Instrument master loaded successfully\"\n      );\n    } catch (error) {\n      logger.error({ err: error }, \"Failed to load instrument master\");\n      throw error;\n    }\n  }\n\n  /**\n   * Get instrument token for a symbol\n   * @param symbol - Trading symbol (e.g., \"RELIANCE-EQ\", \"RELIANCE\")\n   * @param exchange - Exchange segment (e.g., \"NSE\", \"BSE\") - optional\n   * @returns Instrument token or null if not found\n   */\n  getToken(symbol: string, exchange?: string): string | null {\n    if (!this.isLoaded) {\n      logger.warn(\"Instrument master not loaded, call loadInstrumentMaster() first\");\n      return null;\n    }\n\n    // Try with exchange prefix first\n    if (exchange) {\n      const key = `${exchange}:${symbol}`;\n      const token = this.symbolToTokenMap.get(key);\n      if (token) {\n        return token;\n      }\n\n      // Try with -EQ suffix for NSE equity\n      if (exchange === \"NSE\" && !symbol.endsWith(\"-EQ\")) {\n        const eqKey = `${exchange}:${symbol}-EQ`;\n        const eqToken = this.symbolToTokenMap.get(eqKey);\n        if (eqToken) {\n          return eqToken;\n        }\n      }\n    }\n\n    // Fallback to symbol-only lookup\n    const token = this.symbolToTokenMap.get(symbol);\n    if (token) {\n      return token;\n    }\n\n    // Try with -EQ suffix\n    if (!symbol.endsWith(\"-EQ\")) {\n      const eqToken = this.symbolToTokenMap.get(`${symbol}-EQ`);\n      if (eqToken) {\n        return eqToken;\n      }\n    }\n\n    logger.warn({ symbol, exchange }, \"Instrument token not found\");\n    return null;\n  }\n\n  /**\n   * Get full instrument details\n   * @param symbol - Trading symbol\n   * @param exchange - Exchange segment - optional\n   * @returns Instrument details or null if not found\n   */\n  getInstrument(symbol: string, exchange?: string): Instrument | null {\n    if (!this.isLoaded) {\n      logger.warn(\"Instrument master not loaded\");\n      return null;\n    }\n\n    const key = exchange ? `${exchange}:${symbol}` : symbol;\n    return this.instruments.get(key) || null;\n  }\n\n  /**\n   * Search instruments by symbol pattern\n   * @param pattern - Search pattern (case-insensitive)\n   * @param limit - Maximum number of results (default: 10)\n   * @returns Array of matching instruments\n   */\n  searchInstruments(pattern: string, limit = 10): Instrument[] {\n    if (!this.isLoaded) {\n      logger.warn(\"Instrument master not loaded\");\n      return [];\n    }\n\n    const results: Instrument[] = [];\n    const lowerPattern = pattern.toLowerCase();\n\n    for (const instrument of this.instruments.values()) {\n      if (\n        instrument.symbol.toLowerCase().includes(lowerPattern) ||\n        instrument.name.toLowerCase().includes(lowerPattern)\n      ) {\n        results.push(instrument);\n\n        if (results.length >= limit) {\n          break;\n        }\n      }\n    }\n\n    return results;\n  }\n\n  /**\n   * Check if instrument master is loaded\n   */\n  isReady(): boolean {\n    return this.isLoaded;\n  }\n\n  /**\n   * Get total number of instruments loaded\n   */\n  getInstrumentCount(): number {\n    return this.instruments.size;\n  }\n\n  /**\n   * Refresh instrument master (download and reload)\n   */\n  async refresh(): Promise<void> {\n    this.isLoaded = false;\n    this.instruments.clear();\n    this.symbolToTokenMap.clear();\n\n    await this.downloadInstrumentMaster();\n    await this.loadInstrumentMaster();\n  }\n}\n\n// Singleton instance\nlet instrumentMasterService: InstrumentMasterService | null = null;\n\n/**\n * Get singleton instance of InstrumentMasterService\n */\nexport function getInstrumentMasterService(): InstrumentMasterService {\n  if (!instrumentMasterService) {\n    instrumentMasterService = new InstrumentMasterService();\n  }\n  return instrumentMasterService;\n}\n\nexport default InstrumentMasterService;\n"
L184: "text": "This is a comprehensive architectural blueprint to evolve your current single-user algorithmic trading system into a scalable, multi-tenant SaaS platform with an intelligent \"Daily Stock Picker\".\n\n### 1. High-Level Architecture: From Singleton to Multi-Tenant\nThe core shift is moving from a **Global Singleton Container** to a **Scope-Based Container System**.\n\n*   **Current State:** `AppContainer` is created once on startup. Everyone shares the same `PortfolioService` (and thus the same LMDB file).\n*   **Target State:**\n    *   **Global Scope:** Services shared by the entire platform (e.g., `MarketDataService` for feed connection, `InstrumentMasterService`, `AuthService`).\n    *   **User Scope:** Services unique to a user session (e.g., `PortfolioService`, `BrokerClient`, `TradingEngine`).\n\n#### The \"Container Scope\" Pattern\nInstead of `getContainer().portfolioService`, the application will use a factory:\n`ContainerFactory.createForUser(user: UserContext) -> UserContainer`\n\n### 2. User Management & Authentication Layer\nWe need a robust system to manage tenants (users) and their secrets.\n\n*   **New Entities:**\n    *   **User:** `id` (UUID), `email`, `password_hash`, `subscription_tier`.\n    *   **UserConfig:** Stores encrypted broker credentials (`api_key`, `secret`, `access_token`) instead of using `.env`.\n*   **Security:**\n    *   Broker credentials must be encrypted at rest (AES-256).\n    *   **AuthService:** Handles JWT generation and validation.\n    *   **Middleware:** `authMiddleware` validates the JWT and attaches `req.user` to the request.\n\n### 3. Data Layer Partitioning (LMDB)\nWe will maintain the high-performance LMDB file-based approach but partition data physically on the disk.\n\n**Directory Structure:**\n```text\ndata/\n├── global/                  # Shared system data\n│   ├── instruments/         # Instrument Master files\n│   ├── market_history/      # Shared historical data cache\n│   └── users/               # User Auth & Config DB\n└── tenants/                 # Tenant-specific data\n    ├── <user-uuid-1>/       # Isolated directory for User 1\n    │   ├── portfolio/       # Their private Portfolio DB\n    │   ├── settings/        # Their Strategy Settings\n    │   └── audit/           # Their Audit Logs\n    └── <user-uuid-2>/\n```\n\n### 4. The \"Automatic Stock Picker\" (New Intelligence Layer)\nThis feature will scan the market daily to identify trading opportunities.\n\n#### **New Service: `MarketScannerService`**\nThis service runs independently of user sessions, likely as a scheduled job (Cron) before market open.\n\n**Workflow:**\n1.  **Universe Selection:** Queries `InstrumentMasterService` to get all active NSE Equity symbols (e.g., filtered by \"Nifty 500\").\n2.  **Data Fetching:** Uses `HistoricalDataService` to fetch daily candles for the last X days for this universe.\n    *   *Optimization:* Uses a shared `market_history` cache so we don't re-fetch Reliance's data for every user.\n3.  **Analysis:** Applies technical filters using your existing `TechnicalIndicators` library.\n    *   *Criteria Example:* `Close > EMA(200)` AND `RSI(14) < 30` (Oversold in Uptrend).\n    *   *Relative Volume:* `Vol(Today) > SMA(Vol, 20) * 2`.\n4.  **Output:** Generates a `DailyPicks` list.\n\n#### **Integration with Trading Engine:**\n*   **Global Picks:** The system generates a \"System Watchlist\" for the day.\n*   **User Subscription:** Users can configure their strategies to \"Auto-Subscribe\" to the System Watchlist.\n    *   When the user's `TradingEngine` starts, it pulls symbols from `DailyPicks` and subscribes to them via `MarketDataService`.\n\n### 5. Implementation Roadmap\n\n#### **Phase 1: User Identity Foundation**\n1.  Create `UserRepository` (LMDB) to store users.\n2.  Implement `AuthService` for Login/Register.\n3.  Create `EncryptionService` to safely store broker API keys.\n\n#### **Phase 2: Service Refactoring (The Big Shift)**\n1.  **Refactor Repositories:** Update `LmdbPortfolioRepository` and friends to accept a `basePath` in the constructor.\n    ```typescript\n    // BEFORE\n    new LmdbPortfolioRepository(process.env.PORTFOLIO_STORE);\n    \n    // AFTER\n    new LmdbPortfolioRepository(path.join(DATA_DIR, 'tenants', userId, 'portfolio'));\n    ```\n2.  **Refactor Container:** Create a `ContainerFactory` that accepts a `userId` and returns a fully wired `UserContainer`.\n\n#### **Phase 3: The Trading Orchestrator**\nSince we can't have 1000 independent WebSocket connections for 1000 users, we multiplex.\n\n1.  **Global Market Data:** The `MarketDataService` remains a singleton. It connects to the Data Provider (Angel One).\n2.  **Trading Orchestrator:**\n    *   Maintains a registry of Active User Engines.\n    *   When `tick(RELIANCE)` arrives, it checks: \"Which users are trading RELIANCE?\"\n    *   It forwards the tick *only* to those specific user engines.\n\n#### **Phase 4: Build the Stock Picker**\n1.  Implement `MarketScannerService`.\n2.  Create a \"Scanner Strategy\" interface to allow pluggable logic (e.g., \"Gap Up Strategy\", \"Reversal Strategy\").\n3.  Expose an API `/api/market/picks/today` for the frontend dashboard.\n\n### 6. Action Plan for You\nTo get started, I recommend we begin with **Phase 1 (User Identity)**. Shall I proceed with creating the `UserRepository` and basic `User` types?"
---

import { EventEmitter } from "events";
import type { MarketSnapshot, MarketTick } from "../types";
import { RingBuffer } from "../utils/RingBuffer";
import { IncrementalIndicatorSuite } from "./IncrementalIndicators";

export interface UpdateTickInput {
  symbol: string;
  price: number;
  volume: number;
  averagePrice?: number;
  timestamp?: Date | string;
}

export interface SymbolData {
  currentTick: MarketTick;
  tickHistory: RingBuffer<MarketTick>;
  indicators: IncrementalIndicatorSuite;
}

// Default tick history size per symbol
const DEFAULT_HISTORY_SIZE = 1000;

export class MarketDataService extends EventEmitter {
  private readonly symbols = new Map<string, SymbolData>();
  private readonly historySize: number;

  constructor(historySize: number = DEFAULT_HISTORY_SIZE) {
    super();
    this.historySize = historySize;
  }

  /**
   * Update tick for a symbol. O(1) operation including indicator updates.
   */
  updateTick(input: UpdateTickInput): MarketTick {
    const timestamp = input.timestamp instanceof Date ? input.timestamp : new Date(input.timestamp ?? Date.now());
    const symbol = input.symbol.toUpperCase();

    const tick: MarketTick = {
      symbol,
      price: Number(input.price.toFixed(4)),
      volume: Number(input.volume.toFixed(2)),
      averagePrice: input.averagePrice ? Number(input.averagePrice.toFixed(4)) : undefined,
      timestamp,
    };

    let symbolData = this.symbols.get(symbol);
    if (!symbolData) {
      symbolData = {
        currentTick: tick,
        tickHistory: new RingBuffer<MarketTick>(this.historySize),
        indicators: new IncrementalIndicatorSuite(),
      };
      this.symbols.set(symbol, symbolData);
    }

    // Update current tick and history
    symbolData.currentTick = tick;
    symbolData.tickHistory.push(tick);

    // Update incremental indicators (O(1) per indicator)
    symbolData.indicators.update(tick.price);

    this.emit("tick", tick);
    return tick;
  }

  /**
   * Get market snapshot for specified symbols (or all).
   */
  getSnapshot(symbols?: string[]): MarketSnapshot {
    const targetSymbols = symbols
      ? symbols.map(s => s.toUpperCase())
      : Array.from(this.symbols.keys());

    const tickList: MarketTick[] = [];
    for (const symbol of targetSymbols) {
      const data = this.symbols.get(symbol);
      if (data) {
        tickList.push(data.currentTick);
      }
    }

    return {
      ticks: tickList.sort((a, b) => a.symbol.localeCompare(b.symbol)),
      asOf: new Date(),
    };
  }

  /**
   * Get current tick for a symbol.
   */
  getTick(symbol: string): MarketTick | undefined {
    return this.symbols.get(symbol.toUpperCase())?.currentTick;
  }

  /**
   * Get tick history for a symbol.
   */
  getTickHistory(symbol: string, count?: number): MarketTick[] {
    const data = this.symbols.get(symbol.toUpperCase());
    if (!data) return [];
    return count ? data.tickHistory.last(count) : data.tickHistory.toArray();
  }

  /**
   * Get current indicator values for a symbol. O(1) operation (no recalculation).
   */
  getIndicators(symbol: string): ReturnType<IncrementalIndicatorSuite["getValues"]> | undefined {
    return this.symbols.get(symbol.toUpperCase())?.indicators.getValues();
  }

  /**
   * Check if indicators are ready for a symbol.
   */
  indicatorsReady(symbol: string): boolean {
    return this.symbols.get(symbol.toUpperCase())?.indicators.isReady ?? false;
  }

  /**
   * Get all tracked symbols.
   */
  getTrackedSymbols(): string[] {
    return Array.from(this.symbols.keys());
  }
}

export default MarketDataService;

