export type EnvConfig = typeof env;

export default env;

import { EventEmitter } from "events";
import type BrokerClient from "../brokers/BrokerClient";
import PaperBroker from "../brokers/PaperBroker";
import type { RiskManager } from "./RiskManager";
import type MarketDataService from "./MarketDataService";
import PortfolioService from "./PortfolioService";
import type {
  BrokerOrderExecution,
  BrokerOrderFailure,
  BrokerOrderRequest,
  MarketSnapshot,
  PortfolioSnapshot,
  StrategyEvaluationError,
  StrategyExecutionResult,
  StrategySignal,
  Trade,
} from "../types";
import logger from "../utils/logger";
import type BaseStrategy from "../strategies/BaseStrategy";
import { HttpError } from "../utils/HttpError";
import env from "../config/env";

export interface TradingEngineOptions {
  broker: BrokerClient;
  fallbackBroker?: BrokerClient;
  portfolioService: PortfolioService;
  marketData: MarketDataService;
  riskManager: RiskManager;
}

export interface StrategyEvaluationResult {
  strategyId: string;
  snapshot: {
    market: MarketSnapshot;
    portfolio: PortfolioSnapshot;
  };
  executions: StrategyExecutionResult[];
  errors: StrategyEvaluationError[];
}

export class TradingEngine extends EventEmitter {
  private readonly strategies = new Map<string, BaseStrategy>();

  private readonly primaryBroker: BrokerClient;

  private readonly fallbackBroker: BrokerClient;

  private activeBroker: BrokerClient;

  private readonly portfolioService: PortfolioService;

  private readonly marketData: MarketDataService;

  private readonly riskManager: RiskManager;

  constructor(options: TradingEngineOptions) {
    super();
    this.primaryBroker = options.broker;
    this.fallbackBroker = options.fallbackBroker ?? new PaperBroker();
    this.activeBroker = this.primaryBroker;
    this.portfolioService = options.portfolioService;
    this.marketData = options.marketData;
    this.riskManager = options.riskManager;
  }

  getActiveBroker(): BrokerClient {
    return this.activeBroker;
  }

  registerStrategy(strategy: BaseStrategy): void {
    this.strategies.set(strategy.id, strategy);
  }

  getStrategies(): BaseStrategy[] {
    return Array.from(this.strategies.values());
  }

  getStrategy(id: string): BaseStrategy | undefined {
    return this.strategies.get(id);
  }

  private async ensureBrokerConnected(broker: BrokerClient): Promise<void> {
    if (!broker.isConnected()) {
      await broker.connect();
    }
  }

  async connect(): Promise<void> {
    await this.ensureBrokerConnected(this.activeBroker);
  }

  async evaluate(strategyId: string): Promise<StrategyEvaluationResult> {
    const strategy = this.strategies.get(strategyId);
    if (!strategy) {
      throw new HttpError(404, `Unknown strategy ${strategyId}`);
    }

    const errors: StrategyEvaluationError[] = [];

    this.activeBroker = this.primaryBroker;
    try {
      await this.connect();
    } catch (error) {
      const message = error instanceof Error ? error.message : "Failed to connect broker";
      errors.push({ stage: "BROKER_CONNECTION", message, details: this.serializeError(error) });
      logger.error(
        { err: error, strategyId, broker: this.primaryBroker.name },
        "Primary broker connection failed, using paper fallback",
      );

      this.activeBroker = this.fallbackBroker;
      try {
        await this.connect();
      } catch (fallbackError) {
        const fallbackMessage =
          fallbackError instanceof Error ? fallbackError.message : "Failed to connect fallback broker";
        errors.push({
          stage: "BROKER_CONNECTION",
          message: fallbackMessage,
          details: this.serializeError(fallbackError),
        });
        logger.error(
          { err: fallbackError, strategyId, broker: this.fallbackBroker.name },
          "Fallback broker connection failed",
        );

        const marketSnapshot = this.marketData.getSnapshot();
        const portfolioSnapshot = await this.portfolioService.getSnapshot();
        return {
          strategyId,
          snapshot: {
            market: marketSnapshot,
            portfolio: portfolioSnapshot,
          },
          executions: [],
          errors,
        } satisfies StrategyEvaluationResult;
      }
    }

    const marketSnapshot = this.marketData.getSnapshot();
    const portfolioSnapshot = await this.portfolioService.getSnapshot();

    const broker = this.activeBroker;

    let signals: StrategySignal[] = [];
    try {
      signals = await strategy.generateSignals({
        market: marketSnapshot,
        portfolio: portfolioSnapshot,
        broker,
      });
    } catch (error) {
      const message = error instanceof Error ? error.message : "Failed to generate strategy signals";
      errors.push({ stage: "SIGNAL_GENERATION", message, details: this.serializeError(error) });
      logger.error({ err: error, strategyId }, "Strategy signal generation failed");
    }

    const executions: StrategyExecutionResult[] = [];
    for (const signal of signals) {
      try {
        const executed = await this.executeSignal(broker, signal);
        executions.push(executed);
        if (executed.failures.length > 0) {
          errors.push(
            ...executed.failures.map((failure) => ({
              stage: "EXECUTION" as const,
              message: failure.error,
              details: { request: failure.request },
            } satisfies StrategyEvaluationError)),
          );
        }
      } catch (error) {
        const message = error instanceof Error ? error.message : "Failed to execute strategy signal";
        errors.push({ stage: "EXECUTION", message, details: { signal, error: this.serializeError(error) } });
        logger.error({ err: error, strategyId, signalId: signal.strategyId }, "Strategy execution failed");
      }
    }

    return {
      strategyId,
      snapshot: {
        market: marketSnapshot,
        portfolio: portfolioSnapshot,
      },
      executions,
      errors,
    };
  }

  async executeSignal(broker: BrokerClient, signal: StrategySignal): Promise<StrategyExecutionResult> {
    const executions: BrokerOrderExecution[] = [];
    const failures: BrokerOrderFailure[] = [];

    // Check dry-run mode
    if (env.dryRun) {
      logger.info(
        {
          dryRun: true,
          strategyId: signal.strategyId,
          orders: signal.requestedOrders
        },
        "🔍 DRY RUN: Would execute orders (not executing in dry-run mode)"
      );

      // Return mock executions for dry-run mode
      for (const order of signal.requestedOrders) {
        executions.push({
          id: `dry-run-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
          request: order,
          status: "PARTIALLY_FILLED",
          filledQuantity: 0, // No actual fill in dry-run, keep status consistent with simulation
          averagePrice: order.price ?? 0,
          executedAt: new Date(),
        });
      }

      return { signal, executions, failures };
    }

    // Normal execution
    for (const order of signal.requestedOrders) {
      try {
        // Validation (Risk Checks)
        const portfolioSnapshot = await this.portfolioService.getSnapshot();
        const unrealizedPnL = portfolioSnapshot.positions.reduce((sum, p) => sum + p.unrealizedPnl, 0);
        const openPositionsCount = portfolioSnapshot.positions.filter(p => p.netQuantity !== 0).length;

        const riskResult = this.riskManager.checkOrderAllowed(order, unrealizedPnL, openPositionsCount);
        if (!riskResult.allowed) {
          throw new Error(`Risk check failed: ${riskResult.reason}`);
        }

        const execution = await broker.placeOrder(order);
        this.riskManager.recordExecution(execution);
        executions.push(execution);

        if (execution.filledQuantity > 0 && execution.status !== "REJECTED") {
          const trade: Trade = {
            id: execution.id,
            symbol: execution.request.symbol,
            side: execution.request.side,
            quantity: execution.filledQuantity,
            price: execution.averagePrice,
            executedAt: execution.executedAt,
          };
          await this.portfolioService.recordExternalTrade(trade);

          // Emit trade event for stop-loss monitor integration
          this.emit("trade-executed", trade);
        }
      } catch (error) {
        const message = error instanceof Error ? error.message : "Order execution failed";
        failures.push({ request: order, error: message, details: this.serializeError(error) });
        logger.error({ err: error, symbol: order.symbol, side: order.side }, "Broker order execution failed");
      }
    }

    return { signal, executions, failures };
  }

  /**
   * Validates an order before execution
   * Checks position size limits and capital availability
   * @deprecated logic moved to RiskManager
   */
  private validateOrder(order: BrokerOrderRequest): void {
    // Legacy local validation kept as backup or removed? 
    // We can defer to RiskManager completely. 
    // RiskManager handles maxPositionSize now.
    // Capital availability/price checks might still be useful here or moved to RiskManager?
    // For now, let's just minimal checks.

    // Validate price exists and is positive for LIMIT orders
    if (order.type === 'LIMIT' && (!order.price || order.price <= 0)) {
      throw new Error(`Invalid price: ${order.price} (must be > 0)`);
    }

    // Validate quantity is positive
    if (order.quantity <= 0) {
      throw new Error(`Invalid quantity: ${order.quantity} (must be > 0)`);
    }
  }

  private serializeError(error: unknown): unknown {
    if (error instanceof Error) {
      return { message: error.message, stack: error.stack };
    }
    return error;
  }

  async sellAllPositions(): Promise<{ executions: BrokerOrderExecution[]; failures: BrokerOrderFailure[] }> {
    const executions: BrokerOrderExecution[] = [];
    const failures: BrokerOrderFailure[] = [];

    try {
      // 1. Get all open positions from broker
      // Note: We use the broker's position data as the source of truth for liquidation
      await this.connect();
      const positions = await this.activeBroker.getPositions();

      for (const position of positions) {
        if (position.quantity === 0) continue;

        // Determine side to close
        const side = position.quantity > 0 ? "SELL" : "BUY";
        const quantity = Math.abs(position.quantity);

        const order: BrokerOrderRequest = {
          symbol: position.symbol,
          side,
          quantity,
          type: "MARKET",
          tag: `PANIC-SELL-${Date.now()}`,
          price: 0, // Market order
        };

        try {
          const execution = await this.activeBroker.placeOrder(order);
          executions.push(execution);

          if (execution.filledQuantity > 0) {
            const trade: Trade = {
              id: execution.id,
              symbol: execution.request.symbol,
              side: execution.request.side,
              quantity: execution.filledQuantity,
              price: execution.averagePrice,
              executedAt: execution.executedAt,
            };
            await this.portfolioService.recordExternalTrade(trade);
          }
        } catch (error) {
          const message = error instanceof Error ? error.message : "Panic sell failed";
          failures.push({ request: order, error: message, details: this.serializeError(error) });
          logger.error({ err: error, symbol: position.symbol }, "Failed to close position during panic sell");
        }
      }
    } catch (error) {
      logger.error({ err: error }, "Failed to fetch positions for panic sell");
      throw error;
    }

    return { executions, failures };
  }
}

export default TradingEngine;

import type { HistoricalCandle, HistoricalDataRequest } from "../types";
import logger from "../utils/logger";

export interface HistoricalDataCache {
  get(key: string): HistoricalCandle[] | undefined;
  set(key: string, data: HistoricalCandle[], ttlMs: number): void;
  clear(): void;
}

class InMemoryCache implements HistoricalDataCache {
  private cache = new Map<string, { data: HistoricalCandle[]; expires: number; lastAccessed: number }>();
  private readonly maxEntries: number;

  constructor(maxEntries: number = 100) {
    this.maxEntries = maxEntries;
  }

  get(key: string): HistoricalCandle[] | undefined {
    const entry = this.cache.get(key);
    if (!entry || Date.now() > entry.expires) {
      this.cache.delete(key);
      return undefined;
    }

    // Update last accessed time for LRU
    entry.lastAccessed = Date.now();
    return entry.data;
  }

  set(key: string, data: HistoricalCandle[], ttlMs: number): void {
    // Evict LRU entry if cache is full
    if (this.cache.size >= this.maxEntries && !this.cache.has(key)) {
      this.evictLRU();
    }

    this.cache.set(key, {
      data,
      expires: Date.now() + ttlMs,
      lastAccessed: Date.now(),
    });
  }

  /**
   * Evict the least recently used entry from cache
   */
  private evictLRU(): void {
    let oldestKey: string | null = null;
    let oldestTime = Infinity;

    for (const [key, entry] of this.cache.entries()) {
      // Also evict expired entries opportunistically
      if (Date.now() > entry.expires) {
        this.cache.delete(key);
        continue;
      }

      if (entry.lastAccessed < oldestTime) {
        oldestTime = entry.lastAccessed;
        oldestKey = key;
      }
    }

    if (oldestKey) {
      logger.debug({ evictedKey: oldestKey }, "Evicted LRU cache entry");
      this.cache.delete(oldestKey);
    }
  }

  clear(): void {
    this.cache.clear();
  }
}

export interface HistoricalDataProvider {
  fetchHistoricalData(request: HistoricalDataRequest): Promise<HistoricalCandle[]>;
}

class ZerodhaHistoricalProvider implements HistoricalDataProvider {
  async fetchHistoricalData(request: HistoricalDataRequest): Promise<HistoricalCandle[]> {
    logger.info({ symbol: request.symbol, interval: request.interval }, "Fetching historical data from Zerodha");

    // TODO: Implement actual Zerodha historical data API call
    // This would use KiteConnect.getHistoricalData()

    // Mock implementation for now
    const mockData: HistoricalCandle[] = [];
    const startDate = new Date(request.fromDate);
    const endDate = new Date(request.toDate);

    const currentDate = new Date(startDate);
    let price = 100 + Math.random() * 50;

    while (currentDate <= endDate) {
      const dailyChange = (Math.random() - 0.5) * 4; // ±2% daily change
      const open = price;
      const close = price + dailyChange;
      const high = Math.max(open, close) + Math.random() * 2;
      const low = Math.min(open, close) - Math.random() * 2;
      const volume = 10000 + Math.random() * 50000;

      mockData.push({
        symbol: request.symbol,
        open: Number(open.toFixed(2)),
        high: Number(high.toFixed(2)),
        low: Number(low.toFixed(2)),
        close: Number(close.toFixed(2)),
        volume: Math.round(volume),
        timestamp: new Date(currentDate),
      });

      price = close;

      // Increment date based on interval
      if (request.interval === "1day") {
        currentDate.setDate(currentDate.getDate() + 1);
      } else if (request.interval === "1week") {
        currentDate.setDate(currentDate.getDate() + 7);
      } else if (request.interval === "1month") {
        currentDate.setMonth(currentDate.getMonth() + 1);
      }
    }

    return mockData;
  }
}

export class HistoricalDataService {
  private readonly cache: HistoricalDataCache;
  private readonly provider: HistoricalDataProvider;
  private readonly defaultCacheTtl: number;

  constructor(
    cache: HistoricalDataCache = new InMemoryCache(),
    provider: HistoricalDataProvider = new ZerodhaHistoricalProvider(),
    defaultCacheTtlHours = 4
  ) {
    this.cache = cache;
    this.provider = provider;
    this.defaultCacheTtl = defaultCacheTtlHours * 60 * 60 * 1000;
  }

  async getHistoricalData(request: HistoricalDataRequest): Promise<HistoricalCandle[]> {
    const cacheKey = this.buildCacheKey(request);

    // Try cache first
    const cached = this.cache.get(cacheKey);
    if (cached) {
      logger.debug({ symbol: request.symbol, cacheKey }, "Historical data cache hit");
      return cached;
    }

    // Fetch from provider
    logger.info({ symbol: request.symbol, interval: request.interval }, "Fetching historical data");
    const data = await this.provider.fetchHistoricalData(request);

    // Cache the result
    this.cache.set(cacheKey, data, this.defaultCacheTtl);

    return data;
  }

  async getRecentData(symbol: string, days: number = 252): Promise<HistoricalCandle[]> {
    const toDate = new Date();
    const fromDate = new Date();
    fromDate.setDate(fromDate.getDate() - days);

    return this.getHistoricalData({
      symbol,
      interval: "1day",
      fromDate,
      toDate,
    });
  }

  async getWeeklyData(symbol: string, weeks: number = 52): Promise<HistoricalCandle[]> {
    const toDate = new Date();
    const fromDate = new Date();
    fromDate.setDate(fromDate.getDate() - (weeks * 7));

    return this.getHistoricalData({
      symbol,
      interval: "1week",
      fromDate,
      toDate,
    });
  }

  clearCache(): void {
    this.cache.clear();
    logger.info("Historical data cache cleared");
  }

  private buildCacheKey(request: HistoricalDataRequest): string {
    const fromStr = request.fromDate.toISOString().split('T')[0];
    const toStr = request.toDate.toISOString().split('T')[0];
    return `${request.symbol}_${request.interval}_${fromStr}_${toStr}`;
  }
}

export default HistoricalDataService;

import { SmartAPI } from "smartapi-javascript";
import type { SmartApiCandleTuple } from "smartapi-javascript";
import { authenticator } from "otplib";
import type { HistoricalDataProvider } from "../services/HistoricalDataService";
import type { HistoricalCandle, HistoricalDataRequest } from "../types";
import { getInstrumentMasterService } from "../services/InstrumentMasterService";
import logger from "../utils/logger";

export interface AngelOneConfig {
  apiKey: string;
  clientId: string;
  password: string;
  totpSecret?: string;
}

/**
 * Angel One SmartAPI provider for historical market data
 * Provides free access to historical OHLC data for Indian stocks
 */
export class AngelOneHistoricalProvider implements HistoricalDataProvider {
  private smartApi: typeof SmartAPI.prototype;
  private config: AngelOneConfig;
  private isAuthenticated = false;

  constructor(config: AngelOneConfig) {
    this.config = config;
    this.smartApi = new SmartAPI({
      api_key: config.apiKey,
    });
  }

  /**
   * Authenticate with Angel One SmartAPI
   * This should be called before fetching historical data
   */
  async authenticate(): Promise<void> {
    if (this.isAuthenticated) {
      return;
    }

    try {
      // Generate TOTP if totpSecret is provided
      const totp = this.config.totpSecret
        ? this.generateTOTP(this.config.totpSecret)
        : undefined;

      const loginResponse = await this.smartApi.generateSession(
        this.config.clientId,
        this.config.password,
        totp
      );

      if (loginResponse.status && loginResponse.data?.jwtToken) {
        this.smartApi.setAccessToken(loginResponse.data.jwtToken);
        this.isAuthenticated = true;
        logger.info("Angel One authentication successful");
      } else {
        throw new Error("Authentication failed: " + JSON.stringify(loginResponse));
      }
    } catch (error) {
      logger.error({ err: error }, "Failed to authenticate with Angel One");
      throw error;
    }
  }

  async fetchHistoricalData(request: HistoricalDataRequest): Promise<HistoricalCandle[]> {
    if (!this.isAuthenticated) {
      await this.authenticate();
    }

    try {
      const interval = this.mapInterval(request.interval);

      logger.info(
        {
          symbol: request.symbol,
          interval: request.interval,
          from: request.fromDate,
          to: request.toDate
        },
        "Fetching historical data from Angel One"
      );

      // Angel One historical API format
      const params = {
        exchange: "NSE", // TODO: Make this configurable
        symboltoken: await this.getSymbolToken(request.symbol),
        interval,
        fromdate: this.formatDate(request.fromDate),
        todate: this.formatDate(request.toDate),
      };

      const response = await this.smartApi.getCandleData(params);

      if (!response.status || !response.data) {
        throw new Error(`Failed to fetch historical data: ${JSON.stringify(response)}`);
      }

      return this.parseCandles(request.symbol, response.data);
    } catch (error) {
      logger.error(
        { err: error, symbol: request.symbol, interval: request.interval },
        "Error fetching historical data from Angel One"
      );
      throw error;
    }
  }

  /**
   * Get symbol token for a given symbol
   * Angel One requires instrument tokens instead of symbols
   */
  private async getSymbolToken(symbol: string): Promise<string> {
    const instrumentService = getInstrumentMasterService();

    // Ensure instrument master is loaded
    if (!instrumentService.isReady()) {
      try {
        await instrumentService.loadInstrumentMaster();
      } catch (error) {
        logger.error({ err: error, symbol }, "Failed to load instrument master");
        throw new Error(`Cannot fetch token for ${symbol}: instrument master not loaded`);
      }
    }

    // Get token from instrument service
    const token = instrumentService.getToken(symbol, "NSE");

    if (!token) {
      logger.error({ symbol }, "Symbol token not found in instrument master");
      throw new Error(`Symbol token not found for ${symbol}`);
    }

    return token;
  }

  /**
   * Map our interval format to Angel One's interval format
   */
  private mapInterval(interval: HistoricalDataRequest["interval"]): string {
    const intervalMap: Record<HistoricalDataRequest["interval"], string> = {
      "1day": "ONE_DAY",
      "1week": "ONE_WEEK",
      "1month": "ONE_MONTH",
    };

    return intervalMap[interval] || "ONE_DAY";
  }

  /**
   * Format date to Angel One's expected format (YYYY-MM-DD HH:mm)
   */
  private formatDate(date: Date): string {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, "0");
    const day = String(date.getDate()).padStart(2, "0");
    return `${year}-${month}-${day} 09:15`; // Market opens at 9:15 AM IST
  }

  /**
   * Parse Angel One candle data to our HistoricalCandle format
   * Angel One returns: [timestamp, open, high, low, close, volume]
   */
  private parseCandles(symbol: string, data: SmartApiCandleTuple[]): HistoricalCandle[] {
    return data.map((candle) => {
      const [timestamp, open, high, low, close, volume] = candle;

      return {
        symbol,
        open: Number(open),
        high: Number(high),
        low: Number(low),
        close: Number(close),
        volume: Number(volume),
        timestamp: new Date(timestamp),
      };
    });
  }

  /**
   * Generate TOTP for two-factor authentication
   */
  private generateTOTP(secret: string): string {
    try {
      const token = authenticator.generate(secret);
      logger.debug("TOTP generated successfully");
      return token;
    } catch (error) {
      logger.error({ err: error }, "Failed to generate TOTP");
      throw new Error("Failed to generate TOTP code");
    }
  }

  /**
   * Check if provider is authenticated
   */
  isReady(): boolean {
    return this.isAuthenticated;
  }

  /**
   * Disconnect and clear authentication
   */
  async disconnect(): Promise<void> {
    this.isAuthenticated = false;
    logger.info("Angel One provider disconnected");
  }
}

export default AngelOneHistoricalProvider;

