  ];

  constructor(
    historicalDataService: HistoricalDataService,
    instrumentService?: InstrumentMasterService
  ) {
    this.historicalDataService = historicalDataService;
    this.instrumentService = instrumentService || getInstrumentMasterService();
  }

  /**
   * Scan the market for potential trading opportunities
   */
  async scan(): Promise<ScanResult[]> {
    logger.info("Starting market scan...");

    // Ensure instrument master is loaded
    if (!this.instrumentService.isReady()) {
      await this.instrumentService.loadInstrumentMaster();
    }

    const results: ScanResult[] = [];
    const errors: string[] = [];

    // Process symbols in parallel with a concurrency limit
    const batchSize = 5;
    for (let i = 0; i < this.UNIVERSE.length; i += batchSize) {
      const batch = this.UNIVERSE.slice(i, i + batchSize);

      const batchResults = await Promise.allSettled(
        batch.map(symbol => this.analyzeSymbol(symbol))
      );

      for (const result of batchResults) {
        if (result.status === "fulfilled" && result.value) {
          results.push(result.value);
        } else if (result.status === "rejected") {
           // Log but continue
           // logger.warn({ err: result.reason }, "Failed to analyze symbol");
        }
      }
    }

    // Sort by score descending
    const sortedResults = results.sort((a, b) => b.score - a.score);

    logger.info(
      { 
        scanned: this.UNIVERSE.length, 
        selected: sortedResults.length 
      }, 
      "Market scan completed"
    );

    return sortedResults;
  }

  private async analyzeSymbol(symbol: string): Promise<ScanResult | null> {
    try {
      // Fetch daily data for last 200 days (approx 1 year trading days)
      const candles = await this.historicalDataService.getRecentData(symbol, 300);

      if (candles.length < 50) {
        return null; // Not enough data
      }

      // Latest candle
      const latest = candles[candles.length - 1];
      const prices = candles.map(c => c.close);
      const volumes = candles.map(c => c.volume);

      // 1. Trend Filter: Price > SMA(50)
      const sma50 = TechnicalIndicators.calculateSMA(prices, 50);
      const isUptrend = latest.close > sma50;

      if (!isUptrend) return null;

      // 2. Momentum: RSI(14) > 50
      const rsi = TechnicalIndicators.calculateRSI(prices, 14);
      const hasMomentum = rsi > 50 && rsi < 75; // Not overbought yet

      // 3. Volume: Volume > SMA(Volume, 20)
      const avgVolume = TechnicalIndicators.calculateSMA(volumes, 20);
      const volumeRatio = latest.volume / avgVolume;
      const hasVolume = volumeRatio > 1.0;

      if (hasMomentum && hasVolume) {
        return {
          symbol,
          score: (volumeRatio * 10) + (rsi / 10), // Simple scoring algo
          reason: [
            "Price > SMA(50)",
            `RSI ${rsi.toFixed(2)} > 50`,
            `Vol Ratio ${volumeRatio.toFixed(2)} > 1.0`
          ],
          metrics: {
            price: latest.close,
            changePercent: ((latest.close - candles[candles.length - 2].close) / candles[candles.length - 2].close) * 100,
            rsi,
            volumeRatio
          }
        };
      }

      return null;

    } catch (error) {
      logger.debug({ symbol, err: error }, "Error analyzing symbol");
      return null;
    }
  }
}

