import PaperBroker from "./brokers/PaperBroker";
import type BrokerClient from "./brokers/BrokerClient";
import ZerodhaBroker from "./brokers/ZerodhaBroker";
import AngelOneBroker from "./brokers/AngelOneBroker";
import env from "./config/env";
import { getPortfolioRepository, getSettingsRepository, getStopLossRepository, getAuditLogRepository } from "./persistence";
import MarketDataService from "./services/MarketDataService";
import PortfolioService from "./services/PortfolioService";
import TradingEngine from "./services/TradingEngine";
import HistoricalDataService from "./services/HistoricalDataService";
import PortfolioRebalancer from "./services/PortfolioRebalancer";
import ExecutionPlanner from "./services/ExecutionPlanner";
import AngelOneHistoricalProvider from "./providers/AngelOneHistoricalProvider";
import VWAPStrategy from "./strategies/VWAPStrategy";
import type { TickerClient } from "./services/TickerClient";
import AngelOneTickerService from "./services/AngelOneTickerService";
import ReconciliationService from "./services/ReconciliationService";
import { RiskManager } from "./services/RiskManager";
import { StopLossMonitor } from "./services/StopLossMonitor";
import { AuditLogService } from "./services/AuditLogService";
import { HealthService } from "./services/HealthService";
import { NotificationService } from "./services/NotificationService";
import { TunnelService } from "./services/TunnelService";
import { DiscordBotService } from "./services/DiscordBotService";
import type { SettingsRepository } from "./persistence/SettingsRepository";
import type { StopLossRepository } from "./persistence/StopLossRepository";
import type { AuditLogRepository } from "./persistence/AuditLogRepository";

export interface AppContainer {
  portfolioService: PortfolioService;
  marketDataService: MarketDataService;
  historicalDataService: HistoricalDataService;
  portfolioRebalancer: PortfolioRebalancer;
  executionPlanner: ExecutionPlanner;
  brokerClient: BrokerClient;
  tradingEngine: TradingEngine;
  tickerClient: TickerClient | null;
  reconciliationService: ReconciliationService;
  settingsRepository: SettingsRepository;
  stopLossRepository: StopLossRepository;
  auditLogRepository: AuditLogRepository;
  riskManager: RiskManager;
  stopLossMonitor: StopLossMonitor;
  auditLogService: AuditLogService;
  healthService: HealthService;
  notificationService: NotificationService;
  tunnelService: TunnelService;
  discordBotService: DiscordBotService;
}

const buildBroker = (): BrokerClient => {
  switch (env.brokerProvider) {
    case "zerodha":
      return new ZerodhaBroker({
        apiKey: env.brokerApiKey,
        apiSecret: env.brokerApiSecret,
        accessToken: env.brokerAccessToken || process.env.ZERODHA_ACCESS_TOKEN,
        requestToken: env.brokerRequestToken,
        defaultExchange: env.brokerDefaultExchange,
        product: env.brokerProduct,
      });
    case "angelone":
      return new AngelOneBroker({
        apiKey: env.angelOneApiKey,
        clientId: env.angelOneClientId,
        password: env.angelOnePassword,
        totpSecret: env.angelOneTotpSecret,
        defaultExchange: env.angelOneDefaultExchange,
        productType: env.angelOneProductType,
      });
    default:
      return new PaperBroker();
  }
};

const buildHistoricalDataService = (): HistoricalDataService => {
  // Use Angel One provider if broker is set to angelone
  if (env.brokerProvider === "angelone" && env.angelOneApiKey) {
    const provider = new AngelOneHistoricalProvider({
      apiKey: env.angelOneApiKey,
      clientId: env.angelOneClientId,
      password: env.angelOnePassword,
      totpSecret: env.angelOneTotpSecret,
    });
    return new HistoricalDataService(undefined, provider);
  }

  // Default to mock provider
  return new HistoricalDataService();
};

/**
 * Build ticker service based on DATA_PROVIDER config
 * Uses Angel One's free WebSocket ticker for real-time market data
 */
const buildTicker = (marketData: MarketDataService): TickerClient | null => {
  // Use Angel One ticker if data provider is set to angelone
  if (env.dataProvider === "angelone" && env.angelOneApiKey) {
    return new AngelOneTickerService(marketData);
  }
  return null;
};

export const createContainer = (): AppContainer => {
  const portfolioService = new PortfolioService(getPortfolioRepository());
  const settingsRepository = getSettingsRepository();
  const stopLossRepository = getStopLossRepository();
  const marketDataService = new MarketDataService();
  const historicalDataService = buildHistoricalDataService();
  const portfolioRebalancer = new PortfolioRebalancer();
  const executionPlanner = new ExecutionPlanner();
  const brokerClient = buildBroker();
  const riskManager = new RiskManager(settingsRepository);
  const tradingEngine = new TradingEngine({
    broker: brokerClient,
    marketData: marketDataService,
    portfolioService,
    riskManager,
  });

  tradingEngine.registerStrategy(new VWAPStrategy());

  // Build ticker for real-time market data (uses DATA_PROVIDER config)
  const tickerClient = buildTicker(marketDataService);

  // Build reconciliation service for syncing with broker
  const reconciliationService = new ReconciliationService(brokerClient, portfolioService);

  // Build stop-loss monitor
  const stopLossMonitor = new StopLossMonitor({
    marketDataService,
    tradingEngine,
    stopLossRepository,
    riskManager,
  });

  // Build audit log service
  const auditLogRepository = getAuditLogRepository();
  const auditLogService = new AuditLogService({
    repository: auditLogRepository,
    tradingEngine,
    stopLossMonitor,
    settingsRepository,
  });

  // Build health service
  const healthService = new HealthService({
    brokerClient,
    tickerClient: tickerClient || undefined,
    marketDataService,
    stopLossMonitor,
  });

  // Build notification service (only if webhook configured)
  const notificationService = new NotificationService({
    discordWebhookUrl: env.discordWebhookUrl,
    webhookUrl: env.webhookUrl,
    tradingEngine,
    stopLossMonitor,
  });

  // Wire RiskManager critical errors to notifications
  riskManager.on("critical_error", (event: { type: string; error: Error }) => {
    void notificationService.notifyCriticalError(
      event.type,
      event.error?.message || "Unknown error"
    );
  });

  // Build remote access services
  const tunnelService = new TunnelService();

  const discordBotService = new DiscordBotService({
    token: env.discordBotToken,
    tunnelService,
  });

  return {
    portfolioService,
    marketDataService,
    historicalDataService,
    portfolioRebalancer,
    executionPlanner,
    brokerClient,
    tradingEngine,
    tickerClient,
    reconciliationService,
    settingsRepository,
    stopLossRepository,
    auditLogRepository,
    riskManager,
    stopLossMonitor,
    auditLogService,
    healthService,
    notificationService,
    tunnelService,
    discordBotService,
  };
};

let activeContainer: AppContainer | null = null;

export const getContainer = (): AppContainer => {
  if (!activeContainer) {
    activeContainer = createContainer();
  }

  return activeContainer;
};

export const resetContainer = (): AppContainer => {
  activeContainer = createContainer();
  return activeContainer;
};

// For testing purposes
export const setContainer = (container: AppContainer): void => {
  activeContainer = container;
};

export const resolvePortfolioService = (): PortfolioService => getContainer().portfolioService;

export const resolveMarketDataService = (): MarketDataService => getContainer().marketDataService;

export const resolveHistoricalDataService = (): HistoricalDataService => getContainer().historicalDataService;

export const resolvePortfolioRebalancer = (): PortfolioRebalancer => getContainer().portfolioRebalancer;

export const resolveExecutionPlanner = (): ExecutionPlanner => getContainer().executionPlanner;

export const resolveBrokerClient = (): BrokerClient => getContainer().brokerClient;

export const resolveTradingEngine = (): TradingEngine => getContainer().tradingEngine;

export const resolveTickerClient = (): TickerClient | null => getContainer().tickerClient;

export const resolveReconciliationService = (): ReconciliationService => getContainer().reconciliationService;

export const resolveSettingsRepository = (): SettingsRepository => getContainer().settingsRepository;

export const resolveStopLossRepository = (): StopLossRepository => getContainer().stopLossRepository;

export const resolveAuditLogRepository = (): AuditLogRepository => getContainer().auditLogRepository;

export const resolveRiskManager = (): RiskManager => getContainer().riskManager;

export const resolveStopLossMonitor = (): StopLossMonitor => getContainer().stopLossMonitor;

export const resolveAuditLogService = (): AuditLogService => getContainer().auditLogService;

export const resolveHealthService = (): HealthService => getContainer().healthService;

export const resolveNotificationService = (): NotificationService => getContainer().notificationService;

export const resolveDiscordBotService = (): DiscordBotService => getContainer().discordBotService;

import http from "http";
import app from "./app";
import env from "./config/env";
import validateEnvironment from "./config/validateEnv";
import logger from "./utils/logger";
import { ensurePortfolioStore, ensureSettingsStore, ensureStopLossStore, ensureAuditLogStore, getPortfolioRepository } from "./persistence";
import { AuthService } from "./services/AuthService";
import { getInstrumentMasterService } from "./services/InstrumentMasterService";
import { TokenMigrationService } from "./services/TokenMigrationService";
import { TokenRefreshService } from "./services/TokenRefreshService";

const server = http.createServer(app);

// Backup interval tracking
let backupInterval: NodeJS.Timeout | null = null;

/**
 * Schedules automatic database backups
 * Default: Daily backups at the interval specified
 */
const scheduleBackups = async () => {
  const backupIntervalHours = Number(process.env.BACKUP_INTERVAL_HOURS) || 24;
  const backupIntervalMs = backupIntervalHours * 60 * 60 * 1000;

  const performBackup = async () => {
    try {
      const repo = getPortfolioRepository();

      // Only LMDB repository has backup functionality
      if ('createBackup' in repo && typeof repo.createBackup === 'function') {
        const backupPath = await repo.createBackup();
        logger.info({ backupPath }, "Database backup created successfully");
      }
    } catch (error) {
      logger.error({ err: error }, "Failed to create database backup");
    }
  };

  // Create initial backup on startup
  await performBackup();

  // Schedule recurring backups
  backupInterval = setInterval(performBackup, backupIntervalMs);

  logger.info({ intervalHours: backupIntervalHours }, "Automatic backups scheduled");
};

const start = async () => {
  try {
    await validateEnvironment(env);
    await ensurePortfolioStore();
    await ensureSettingsStore();
    await ensureStopLossStore();
    await ensureAuditLogStore();

    // Migrate tokens from file-based storage to LMDB (one-time operation)
    const migrationService = new TokenMigrationService();
    await migrationService.migrate(env.portfolioStorePath);

    const authService = AuthService.getInstance();
    await authService.initialize();

    if (env.brokerProvider !== "paper") {
      const { resolveBrokerClient } = await import("./container");
      const broker = resolveBrokerClient();

      await broker.connect();

      if (!broker.isConnected()) {
        logger.error({
          brokerProvider: env.brokerProvider
        }, "FATAL: Broker not authenticated. Run authentication first.");
        process.exit(1);
      }
      logger.info({ broker: broker.name }, "Broker authentication verified");
    }

    // For ticker (DATA_PROVIDER=angelone), validate Angel One tokens exist
    let tickerTokensValid = false;
    if (env.dataProvider === "angelone") {
      const { loadAngelToken } = await import("./routes/auth");
      const { TokenRefreshService } = await import("./services/TokenRefreshService");
      const refreshService = TokenRefreshService.getInstance();
      let angelTokens = await loadAngelToken();

      if (!angelTokens) {
        if (env.angelOneTotpSecret) {
          logger.info("Angel One tokens missing or expired. Attempting automatic re-authentication...");
          try {
            await refreshService.refreshToken();
            angelTokens = await loadAngelToken();
          } catch (error) {
            logger.warn({ err: error }, "Automatic Angel One re-authentication failed");
          }
        }
        logger.warn("Angel One tokens not found. Ticker will not start. Authenticate via /api/auth/angelone/login");
      } else {
        // Check token expiry
        const expiresAt = new Date(angelTokens.expiresAt);
        if (expiresAt < new Date()) {
          logger.warn({ expiresAt }, "Angel One tokens expired. Ticker will not start. Re-authenticate via /api/auth/angelone/login");
        } else {
          tickerTokensValid = true;
          logger.info("Angel One token validation passed");
        }
      }
    }


    if (env.brokerProvider === "angelone" || env.dataProvider === "angelone") {
      try {
        const instrumentService = getInstrumentMasterService();
        await instrumentService.loadInstrumentMaster();
      } catch (error) {
        logger.warn({ err: error }, "Failed to load instrument master (will retry on first API call)");
      }
    }

    const { resolveTickerClient } = await import("./container");
    const tickerClient = resolveTickerClient();
    if (tickerClient && tickerTokensValid) {
      // Connect ticker (will load tokens internally)
      tickerClient.connect().catch(err => {
        logger.error({ err }, "Failed to connect ticker on startup");
      });
      logger.info("Ticker service initialized");

      // Subscribe to watchlist symbols
      if (env.watchlist.length > 0) {
        // Ensure instrument master is loaded
        const instrumentService = getInstrumentMasterService();
        if (!instrumentService.isReady()) {
           await instrumentService.loadInstrumentMaster();
        }

        const exchange = env.angelOneDefaultExchange;
        let subscribedCount = 0;

        for (const symbol of env.watchlist) {
          const token = instrumentService.getToken(symbol, exchange);
          if (token) {
            tickerClient.subscribe({
              exchange,
              symbol,
              symbolToken: token,
            });
            subscribedCount++;
          } else {
            logger.warn({ symbol, exchange }, "Skipping watchlist subscription: Instrument token not found");
          }
        }

        if (subscribedCount > 0) {
          logger.info({ count: subscribedCount, symbols: env.watchlist }, "Subscribed to watchlist symbols");
        }
      }
    } else if (tickerClient && !tickerTokensValid) {
      logger.info("Ticker service not started - authenticate first");
    }

    // Start backup scheduler
    await scheduleBackups();

    // Start automatic token refresh scheduler (Angel One only)
    const tokenRefreshService = TokenRefreshService.getInstance();
    tokenRefreshService.start();

    // Reconcile positions with broker on startup (critical for consistency)
    const { resolveReconciliationService } = await import("./container");
    const reconciliationService = resolveReconciliationService();
    try {
      const result = await reconciliationService.reconcileOnStartup();
      if (result.hasDiscrepancies) {
        logger.warn(
          { discrepancies: result.discrepancies.length, synced: result.syncedSymbols.length },
          "Position discrepancies found - check dashboard for details"
        );
      }
    } catch (err) {
      logger.error({ err }, "Position reconciliation failed on startup");
    }

    // Initialize Trading Loop Service (but don't start it yet)
    const { resolveMarketDataService, resolveTradingEngine, resolveStopLossMonitor, resolveRiskManager, resolveNotificationService } = await import("./container");
    const { TradingLoopService } = await import("./services/TradingLoopService");
    TradingLoopService.getInstance(resolveMarketDataService(), resolveTradingEngine());
    logger.info("Trading loop service initialized");

    const riskManager = resolveRiskManager();
    const notificationService = resolveNotificationService();
    riskManager.on("critical_error", (event: { type: string; error: Error }) => {
      logger.error({ event }, "CRITICAL ERROR: System may require manual intervention");
      void notificationService.notifyCriticalError(
        event.type,
        event.error?.message || "Unknown error"
      );
    });

    // Initialize Stop-Loss Monitor (starts automatically with trading loop)
    const stopLossMonitor = resolveStopLossMonitor();
    logger.info({ activeStopLosses: stopLossMonitor.getAll().length }, "Stop-loss monitor initialized");

    const { resolveDiscordBotService } = await import("./container");
    const discordBotService = resolveDiscordBotService();
    void discordBotService.start();

    server.listen(env.port, () => {
      logger.info({ port: env.port }, "HTTP server is listening");
    });
  } catch (error) {
    logger.error({ err: error }, "Failed to start server");
    process.exit(1);
  }
};

void start();

const shutdown = (signal: string) => {
  logger.info({ signal }, "Received shutdown signal");

  // Clear backup interval
  if (backupInterval) {
    clearInterval(backupInterval);
    backupInterval = null;
  }

  // Stop token refresh scheduler
  const tokenRefreshService = TokenRefreshService.getInstance();
  tokenRefreshService.stop();

  server.close((error) => {
    if (error) {
      logger.error({ err: error }, "Error during shutdown");
      process.exitCode = 1;
    }
    logger.info("Server closed");
    process.exit();
  });
};

process.on("SIGTERM", () => shutdown("SIGTERM"));
process.on("SIGINT", () => shutdown("SIGINT"));

